/**
 * @title No search results
 * @description Keeps the search and filters in view, says what matched nothing, suggests fixes and offers to clear everything in one step.
 * @route /customers
 */
import { TopBar } from "@/components/top-bar";
import { CustomerSearch } from "@/components/customer-search";

export default function Page() {
  return (
    <div className="flex min-h-svh flex-col bg-canvas">
      <TopBar current="Customers" />
      <main id="main" className="mx-auto flex w-full max-w-5xl flex-1 flex-col gap-6 px-4 py-8 md:px-6">
        <h1 className="text-heading-h2">Customers</h1>
        <CustomerSearch />
      </main>
    </div>
  );
}

"use client";
import { Gauge } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";

const links = ["Overview", "Customers", "Products", "Settings"];

/** A header-only app layout: logo, top navigation and the account menu. */
export function TopBar({ current = "Overview" }: { current?: string }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] border-b border-line-default bg-surface">
      <div className="mx-auto flex h-14 max-w-7xl items-center gap-6 px-4 md:px-6">
        <a href="#" className="flex items-center gap-2 rounded-sm text-label-large focus-visible:focus-ring">
          <span className="grid size-7 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={Gauge} size={16} /></span>
          Acme
        </a>
        <nav aria-label="Main" className="max-md:hidden">
          <ul className="flex items-center gap-1">
            {links.map((l) => (
              <li key={l}>
                <a href="#" aria-current={l === current ? "page" : undefined}
                  className="flex h-8 items-center rounded-control px-3 text-label-medium text-fg-secondary hover:bg-neutral-hover hover:text-fg-primary focus-visible:focus-ring aria-[current=page]:text-fg-primary">
                  {l}
                </a>
              </li>
            ))}
          </ul>
        </nav>
        <div className="ms-auto">
          <Menu
            label="Account menu for Jane Cooper"
            items={[{ label: "Profile", icon: "user" }, { label: "Settings", icon: "settings" }, { label: "Sign out", icon: "sign-out", separatorBefore: true }]}
            trigger={({ ref, ...p }) => (
              <button ref={ref} type="button" {...p} aria-label="Account menu for Jane Cooper" className="rounded-full focus-visible:focus-ring">
                <Avatar name="Jane Cooper" decorative />
              </button>
            )}
          />
        </div>
      </div>
    </header>
  );
}

"use client";
import { useState } from "react";
import { SearchX } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Chip, SearchField } from "@/components/ui/form";
import { Icon } from "@/components/ui/icon";

export function CustomerSearch() {
  const [q, setQ] = useState("harbour labs");
  const [filters, setFilters] = useState(["Active", "Enterprise"]);
  const cleared = !q && !filters.length;
  return (
    <>
      <div className="flex flex-wrap items-center gap-2">
        <div className="w-full sm:w-72"><SearchField label="Search customers" value={q} onChange={setQ} onClear={() => setQ("")} /></div>
        {filters.map((f) => <Chip key={f} onRemove={() => setFilters((x) => x.filter((y) => y !== f))}>{f}</Chip>)}
      </div>
      <section aria-live="polite" className="flex flex-col items-center gap-4 rounded-container border border-line-default bg-surface px-6 py-14 text-center">
        {cleared ? (
          <p className="text-body-medium text-fg-secondary">Showing all 248 customers.</p>
        ) : (
          <>
            <span className="grid size-12 place-items-center rounded-full bg-surface-subtle text-icon-primary"><Icon name={SearchX} /></span>
            <h2 className="text-heading-h4">No customers match {q ? <>“{q}”</> : "these filters"}</h2>
            <div className="flex max-w-sm flex-col gap-1 text-body-small text-fg-secondary">
              <p>Try one of these:</p>
              <ul className="list-inside list-disc text-start">
                <li>Check the spelling — did you mean <button type="button" onClick={() => setQ("harbor labs")} className="rounded-sm text-fg-brand underline underline-offset-2 focus-visible:focus-ring">harbor labs</button>?</li>
                <li>Remove a filter, or search all plans</li>
                <li>Search by email or customer ID</li>
              </ul>
            </div>
            <Button variant="secondary" onClick={() => { setQ(""); setFilters([]); }}>Clear search and filters</Button>
          </>
        )}
      </section>
    </>
  );
}
